import { db } from "@/lib/db";
import type { UserWithRoles } from "@/lib/permissions";

/** Load a user and nested role assignments for session / map access checks. */
export async function loadUserWithRoles(
  userId: string,
): Promise<UserWithRoles | null> {
  const user = await db
    .selectFrom("User")
    .select(["id", "email", "name", "phone", "createdAt"])
    .where("id", "=", userId)
    .executeTakeFirst();

  if (!user) {
    return null;
  }

  const roleRows = await db
    .selectFrom("UserRole")
    .innerJoin("Role", "Role.id", "UserRole.roleId")
    .where("UserRole.userId", "=", userId)
    .select([
      "UserRole.id",
      "UserRole.userId",
      "UserRole.roleId",
      "UserRole.precinctId",
      "UserRole.blockId",
      "UserRole.permissions",
      "Role.id as roleTableId",
      "Role.name as roleName",
    ])
    .execute();

  return {
    ...user,
    roles: roleRows.map((row) => ({
      id: row.id,
      userId: row.userId,
      roleId: row.roleId,
      precinctId: row.precinctId,
      blockId: row.blockId,
      permissions: row.permissions,
      role: {
        id: row.roleTableId,
        name: row.roleName,
      },
    })),
  };
}
